package com.primehr.security;import com.primehr.integration.administrative.*;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class PerformanceInterventionPermissionGuardTest{private final AdministrativeAuthorizationClient client=mock(AdministrativeAuthorizationClient.class);private final PerformanceInterventionPermissionGuard guard=new PerformanceInterventionPermissionGuard(client);@Test void administratorIsAgencyWideForLifecycleActions(){when(client.resolve(PerformanceInterventionPermissionGuard.FEATURE,"admin")).thenReturn(new EffectiveFeaturePermission(PerformanceInterventionPermissionGuard.FEATURE,true,false,false,false,false,false,false,false,false,false,false,PermissionDataScope.NONE));assertThat(guard.require(PrimeHrAction.FINALIZE,"admin")).isEqualTo(PermissionDataScope.AGENCY_WIDE);}}
